<?php
require_once __DIR__ . '/auth.php';
$id = (int)($_GET['id'] ?? $_POST['id'] ?? 0);
if ($id <= 0) { header('Location: users.php'); exit; }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $fullName = trim($_POST['full_name'] ?? ''); $email = trim($_POST['email'] ?? '');
    $phone = trim($_POST['contact_number'] ?? ''); $address = trim($_POST['address'] ?? '');
    $position = trim($_POST['position'] ?? ''); $department = trim($_POST['department'] ?? '');
    $status = $_POST['employment_status'] ?? 'Regular';
    if ($fullName === '' || !filter_var($email, FILTER_VALIDATE_EMAIL) || $position === '' || $department === '') {
        $error = 'Please complete the required fields.';
    } else {
        $stmt = $conn->prepare("UPDATE employees SET full_name=?, email=?, contact_number=?, address=?, position=?, department=?, employment_status=? WHERE id=?");
        $stmt->bind_param('sssssssi', $fullName, $email, $phone, $address, $position, $department, $status, $id);
        if ($stmt->execute()) { header('Location: users.php?updated=1'); exit; }
        $error = 'Unable to update the employee. Please check if the email is already used.';
    }
}
$stmt = $conn->prepare("SELECT * FROM employees WHERE id=? LIMIT 1"); $stmt->bind_param('i',$id); $stmt->execute(); $employee=$stmt->get_result()->fetch_assoc();
if (!$employee) { header('Location: users.php'); exit; }
?>
